using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using Debug=UnityEngine.Debug;
using Object=UnityEngine.Object;
namespace MassiveArmy.EditorTools {
    public static class AtmosphereLimbValidation {
        [Serializable]sealed class Report {public string status="PASS",error="",scope="Editor isolated 2560x1440 GPU atmosphere draws, fenced CPU+GPU latency; not standalone frame/fog/fleet acceptance.";public List<string> checks=new List<string>();public double uniformMedianMs,uniformP95Ms,variedMedianMs,variedP95Ms;public int changedPixels;}
        [InitializeOnLoadMethod]static void Install(){EditorApplication.update-=Pump;EditorApplication.update+=Pump;}
        static void Pump(){const string request="TestResults/Planetary/Reentry/limb-request.txt";if(EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists(request))return;File.Delete(request);Run();}
        [MenuItem("Synthetic Front/Diagnostics/Validate atmosphere limb variation")]
        public static void Run(){
            var report=new Report();Material material=null;Texture3D noise=null;Texture2D depth=null;RenderTexture light=null,transmission=null,target=null,columns=null;CommandBuffer command=null;
            void Check(bool valid,string label){if(!valid)throw new InvalidOperationException(label);report.checks.Add(label);}
            void Draw(){command.Clear();command.DisableScissorRect();command.SetRenderTarget(light);command.ClearRenderTarget(false,true,Color.clear);command.SetRenderTarget(transmission);command.ClearRenderTarget(false,true,Color.white);command.SetRenderTarget(new[]{new RenderTargetIdentifier(light),new RenderTargetIdentifier(transmission)},BuiltinRenderTextureType.None);command.SetViewport(new Rect(0,0,light.width,light.height));command.DrawProcedural(Matrix4x4.identity,material,1,MeshTopology.Triangles,6);command.SetRenderTarget(target);command.SetViewport(new Rect(0,0,target.width,target.height));command.ClearRenderTarget(false,true,new Color(.01f,.01f,.015f,1));command.DrawProcedural(Matrix4x4.identity,material,3,MeshTopology.Triangles,3);command.DrawProcedural(Matrix4x4.identity,material,4,MeshTopology.Triangles,3);Graphics.ExecuteCommandBuffer(command);var read=AsyncGPUReadback.Request(target,0,0,1,0,1,0,1,TextureFormat.RGBAFloat);read.WaitForCompletion();if(read.hasError)throw new InvalidOperationException("Limb fixture GPU readback failed");}
            Color32[] Capture(string name){var read=AsyncGPUReadback.Request(target,0,TextureFormat.RGBA32);read.WaitForCompletion();if(read.hasError)throw new InvalidOperationException("Limb image readback failed");var image=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false,true);try{image.LoadRawTextureData(read.GetData<byte>());image.Apply();File.WriteAllBytes("TestResults/Planetary/Reentry/"+name+".png",image.EncodeToPNG());return image.GetPixels32();}finally{Object.DestroyImmediate(image);}}
            double[] Measure(Vector4 variation){material.SetVector("_AirVariation",variation);for(int i=0;i<8;i++)Draw();var samples=new double[40];for(int i=0;i<samples.Length;i++){var timer=Stopwatch.StartNew();Draw();samples[i]=timer.Elapsed.TotalMilliseconds;}Array.Sort(samples);return samples;}
            RenderTexture RT(int w,int h){var texture=new RenderTexture(w,h,0,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear);texture.Create();return texture;}
            try{
                Directory.CreateDirectory("TestResults/Planetary/Reentry");material=new Material(Resources.Load<Shader>("MassiveArmy/PlanetWeather"));foreach(var message in ShaderUtil.GetShaderMessages(material.shader))Debug.LogError("Atmosphere shader: "+message.message+" at "+message.file+":"+message.line);Check(material.shader.isSupported&&!ShaderUtil.ShaderHasError(material.shader),"Atmosphere shader is supported and error free");command=new CommandBuffer{name="Isolated atmospheric limb variation"};const int width=2560,height=1440;light=RT(width/2,height/2);transmission=RT(width/2,height/2);target=RT(width,height);depth=new Texture2D(width,height,TextureFormat.RFloat,false,true);depth.SetPixelData(new float[width*height],0);depth.Apply(false,true);
                noise=new Texture3D(64,64,64,TextureFormat.R8,true){filterMode=FilterMode.Trilinear,wrapMode=TextureWrapMode.Repeat};var bytes=new byte[64*64*64];for(int i=0;i<bytes.Length;i++){uint value=(uint)i+8317;value^=value>>16;value*=0x7feb352d;value^=value>>15;value*=0x846ca68b;value^=value>>16;bytes[i]=(byte)value;}noise.SetPixelData(bytes,0);noise.Apply(true,true);material.SetTexture("_WeatherNoise",noise);
                columns=new RenderTexture(128,64,0,RenderTextureFormat.RGFloat,RenderTextureReadWrite.Linear){dimension=TextureDimension.Tex2DArray,volumeDepth=17,enableRandomWrite=true,filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};columns.Create();var compute=Resources.Load<ComputeShader>("MassiveArmy/PlanetAirOpticalDepth");compute.SetFloat("_AirHeight",.08333333f);compute.SetInt("_AirSlice",0);compute.SetTexture(0,"_AirColumnsWrite",columns);compute.Dispatch(0,16,8,1);material.SetTexture("_AirColumns",columns);
                material.SetTexture("_WeatherLocalDepth",depth);material.SetTexture("_WeatherSceneDepth",depth);material.SetTexture("_WeatherIntegrated",light);material.SetTexture("_WeatherTransmission",transmission);material.SetVector("_WeatherFullSize",new Vector4(width,height,1f/width,1f/height));material.SetVector("_WeatherHalfSize",new Vector4(width/2,height/2,2f/width,2f/height));material.SetVector("_WeatherBounds",new Vector4(-1,-1,1,1));material.SetVector("_WeatherView",new Vector4(16f/9,Mathf.Tan(30*Mathf.Deg2Rad),1,0));material.SetVector("_WeatherAtmosphere",new Vector4(.08333333f,.45f,.018f,.013f));material.SetFloat("_WeatherRadius",120000);material.SetFloat("_WeatherPrecisionEnabled",1);material.SetVector("_AirScattering",new Vector4(1,0,1,1));material.SetVector("_WeatherSunColour",Vector3.one);material.SetVector("_WeatherSun",new Vector3(1,.15f,-.3f).normalized);material.SetVector("_WeatherWind",new Vector4(0,1,13,0));material.SetVector("_AirGravityTide",new Vector4(.3f,.9f,0,1));material.SetVector("_WeatherCloud",Vector4.zero);material.SetVector("_WeatherCabinEye",Vector4.zero);
                var eye=new Vector3(0,0,-2.2f);var forward=new Vector3(.45f,0,1).normalized;var right=Vector3.Cross(Vector3.up,forward).normalized;material.SetVector("_WeatherCentre",-eye);material.SetFloat("_WeatherEyeAltitude",eye.magnitude-1);material.SetVector("_WeatherForward",forward);material.SetVector("_WeatherRight",right);material.SetVector("_WeatherUp",Vector3.Cross(forward,right));
                command.SetRenderTarget(target);command.ClearRenderTarget(false,true,Color.white);Graphics.ExecuteCommandBuffer(command);var sanity=AsyncGPUReadback.Request(target,0,0,1,0,1,0,1,TextureFormat.RGBAFloat);sanity.WaitForCompletion();Debug.Log("Limb GPU clear "+sanity.GetData<Color>()[0]+" device "+SystemInfo.graphicsDeviceType);var uniform=Measure(Vector4.zero);var control=Capture("UniformLimb");var values=AsyncGPUReadback.Request(light,0,light.width/2,1,light.height/2,1,0,1,TextureFormat.RGBAFloat);values.WaitForCompletion();Debug.Log("Limb light "+values.GetData<Color>()[0]);var varied=Measure(new Vector4(.06f,8,.025f,.012f));var result=Capture("VariedLimb");report.uniformMedianMs=uniform[20];report.uniformP95Ms=uniform[38];report.variedMedianMs=varied[20];report.variedP95Ms=varied[38];for(int i=0;i<result.Length;i++)if(Math.Abs(result[i].r-control[i].r)+Math.Abs(result[i].g-control[i].g)+Math.Abs(result[i].b-control[i].b)>2)report.changedPixels++;
                Check(report.changedPixels>1000,"Large-scale density noise and tide terms change visible atmospheric limb pixels");Check(!ShaderUtil.ShaderHasError(material.shader),"Atmosphere shader compiles on the editor graphics device");
            }catch(Exception e){report.status="FAIL";report.error=e.ToString();Debug.LogException(e);}finally{command?.Dispose();foreach(var texture in new[]{light,transmission,target,columns})if(texture!=null){texture.Release();Object.DestroyImmediate(texture);}if(material!=null)Object.DestroyImmediate(material);if(depth!=null)Object.DestroyImmediate(depth);if(noise!=null)Object.DestroyImmediate(noise);Directory.CreateDirectory("TestResults/Planetary/Reentry");File.WriteAllText("TestResults/Planetary/Reentry/limb-validation.json",JsonUtility.ToJson(report,true));Debug.Log("Atmosphere limb validation "+report.status);}
        }
    }
}
